  read(key) {                                          // decorated method
    const t0 = this.clock.now();
    const value = this.inner.read(key);                // delegate
    this.clock.record('read', t0);
    return value;
  }
  write(key, value) { return this.inner.write(key, value); }  // pass-through
}
